#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── Helpers of this wizard ─────────────────────────────────────────────────
VPS_IP_DEFAULT="51.68.121.128"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SERVER_SCRIPT="$SCRIPT_DIR/server/fygs-firewall.sh"
REMOTE_SCRIPT="/usr/local/sbin/fygs-firewall.sh"
# Every site served by this shared server: compared before and after (a firewall mistake would show here first)
SITES=(
  "https://fygs.dev/fr"
  "https://bonsprofs.com/"
  "https://preprod.bonsprofs.com/"
  "https://educonnect.anumerique.com/"
  "https://prisma-consulting-uat.51.68.121.128.sslip.io/"
  "https://fygs-v2.51.68.121.128.sslip.io/api/health"
  "https://deploy.bonsprofs.com/"
)
BASELINE_FILE=""

rssh() { ssh -o BatchMode=yes -o ConnectTimeout=10 -p "$SSH_PORT" "$SSH_TARGET" "$@"; }
# run a command as root on the server (sudo when the login is not root)
rroot() { if [[ "$SSH_TARGET" == root@* ]]; then rssh "$1"; else rssh "sudo -n sh -c $(printf '%q' "$1")"; fi; }

probe_sites() {
  local out="$1" url
  : > "$out"
  for url in "${SITES[@]}"; do
    printf '%s %s\n' "$(curl -s -m 20 -o /dev/null -w '%{http_code}' "$url" || echo 000)" "$url" >> "$out"
  done
}

tcp_open() { timeout 4 bash -c "exec 3<>/dev/tcp/$1/$2" 2>/dev/null; }

run_wizard() {

TOTAL_STAGES=10
ENV_FILE="${WIZARD_ENV_FILE:-$HOME/.config/fygs-dev/firewall.env}"   # the library defaults to ./.env: never write secrets there
mkdir -p "$(dirname "$ENV_FILE")"

banner "fygs.dev: close SSH, Coolify (8000) and realtime/terminal (6001, 6002) to the public (issue #41)"

# ── 1. Preflight ───────────────────────────────────────────────────────────
stage "Before touching the server"
say "This server is SHARED: Bons Profs, prisma, BRVM, Educonnect and fygs.dev all run on it."
say "The wizard measures every site before and after, installs the rules with an automatic undo,"
say "and only keeps them after you proved that a fresh SSH connection still works."
say ""
warn "Warn the people who use the other projects: a mistake would affect them too."
warn "Keep the provider's console (OVH Manager → the VPS → KVM / rescue mode) open in a tab: it is your way back in if everything fails."
[[ -f "$SERVER_SCRIPT" ]] || { warn "missing $SERVER_SCRIPT"; exit 1; }
for tool in ssh scp curl; do command -v "$tool" >/dev/null 2>&1 && say "✓ $tool" || { warn "$tool is missing"; exit 1; }; done
confirm "Ready?" || { say "Nothing was changed."; exit 0; }

# ── 2. SSH target ──────────────────────────────────────────────────────────
stage "SSH access"
ask SSH_TARGET "SSH login (user@host) [e.g. root@$VPS_IP_DEFAULT]:"
ask SSH_PORT "SSH port [22]:"
SSH_PORT="${SSH_PORT:-22}"
write_env SSH_TARGET "$SSH_TARGET"
write_env SSH_PORT "$SSH_PORT"
say "Testing a key-based login (no password prompt is possible here)…"
if rssh 'echo "connected as $(id -un) on $(hostname)"'; then
  say "${GREEN}✓${RESET} SSH works"
else
  warn "SSH with a key failed. Load your key (ssh-add) or fix access, then re-run."; exit 1
fi
if [[ "$SSH_TARGET" != root@* ]]; then
  rroot true 2>/dev/null && say "${GREEN}✓${RESET} passwordless sudo works" || { warn "sudo -n failed: log in as root or allow passwordless sudo for this session"; exit 1; }
fi
pause

# ── 3. Inspect ─────────────────────────────────────────────────────────────
stage "What listens on the server today"
rroot 'echo "--- os:"; (. /etc/os-release && echo "$PRETTY_NAME"); echo "--- listeners (tcp):"; ss -tlnH | awk "{print \$4}" | sort -u | tr "\n" " "; echo; echo "--- iptables / ufw:"; command -v iptables >/dev/null && echo "iptables present" || echo "NO iptables"; command -v ufw >/dev/null && ufw status | head -3 || true; echo "--- docker published ports:"; docker ps --format "{{.Names}}: {{.Ports}}" 2>/dev/null | grep -E "8000|6001|6002" | cut -c1-120 || true' || warn "inspection failed"
say ""
say "Public view of this server right now, from this machine:"
for p in 22 80 443 8000 6001 6002; do tcp_open "$VPS_IP_DEFAULT" "$p" && say "  port $p  OPEN" || say "  port $p  closed/filtered"; done
say ""
say "Baseline of every site (saved to compare after the change):"
BASELINE_FILE="$(mktemp)"
probe_sites "$BASELINE_FILE"
cat "$BASELINE_FILE" | sed 's/^/  /'
pause

# ── 4. Admin addresses ─────────────────────────────────────────────────────
stage "Who may reach 22, 8000, 6001 and 6002"
my4=$(curl -s -m 10 https://api.ipify.org || true)
my6=$(curl -s -m 10 https://api6.ipify.org || true)
say "Your public IPv4: ${my4:-unknown}"
say "Your public IPv6: ${my6:-none}"
say ""
warn "If your home or office address changes, you will be locked out of SSH and the dashboard by address."
note "A stable fix is a VPN with a fixed exit address (WireGuard on a small VPS, Tailscale exit node), then list that address here."
note "Until then, the provider console (KVM / rescue) is the way back in. Add every address you may connect from."
say ""
ask ADMIN_ADDRESSES "Admin addresses, space separated (CIDR ok) [Enter = ${my4:-your IPv4}]:"
ADMIN_ADDRESSES="${ADMIN_ADDRESSES:-$my4}"
[[ -n "$ADMIN_ADDRESSES" ]] || { warn "at least one address is required"; exit 1; }
for a in $ADMIN_ADDRESSES; do
  [[ "$a" =~ ^[0-9a-fA-F:.]+(/[0-9]{1,3})?$ ]] || { warn "not an address: $a"; exit 1; }
done
write_env ADMIN_ADDRESSES "$ADMIN_ADDRESSES"
note "The server also lets private ranges through (Coolify reaches the host's SSH from its own container)."
pause

# ── 5. Install with a dead-man switch ──────────────────────────────────────
stage "Install the rules, with an automatic undo after 2 minutes"
say "Public rules stay as they are: 80 and 443 remain open. Only 22, 8000, 6001 and 6002 become admin-only."
say ""
confirm "Copy the script and apply the rules now?" || { say "Nothing was changed."; exit 0; }
scp -o BatchMode=yes -P "$SSH_PORT" "$SERVER_SCRIPT" "$SSH_TARGET:/tmp/fygs-firewall.sh" >/dev/null
rroot "install -m 0750 /tmp/fygs-firewall.sh $REMOTE_SCRIPT && rm -f /tmp/fygs-firewall.sh"
rroot "$REMOTE_SCRIPT apply-guarded '$ADMIN_ADDRESSES' 120"
say ""
say "Now prove that you can still get in: a NEW connection, then it creates the keep file."
if rssh "touch /run/fygs-fw-keep 2>/dev/null || sudo -n touch /run/fygs-fw-keep"; then
  say "${GREEN}✓${RESET} a fresh SSH connection works with the rules on: the undo is cancelled"
else
  warn "The new connection FAILED. The rules remove themselves within 2 minutes; wait, then check your admin address and re-run."
  exit 1
fi
pause

# ── 6. Compare ─────────────────────────────────────────────────────────────
stage "Did anything else break?"
AFTER_FILE="$(mktemp)"
probe_sites "$AFTER_FILE"
if diff -q "$BASELINE_FILE" "$AFTER_FILE" >/dev/null; then
  say "${GREEN}✓${RESET} every site answers exactly as before"
else
  warn "Some answers changed:"
  diff "$BASELINE_FILE" "$AFTER_FILE" | sed 's/^/  /' || true
  confirm "Undo the rules now?" && { rroot "$REMOTE_SCRIPT rollback"; say "Rules removed."; exit 1; }
fi
say ""
step "Open https://deploy.bonsprofs.com in your browser: log in, open a project, watch a deployment log update live."
note "If live updates stop working only, the dashboard uses port 6001 directly from your browser: it works from an admin address."
confirm "Does the Coolify dashboard work normally?" || { rroot "$REMOTE_SCRIPT rollback"; warn "Rules removed. Tell me what broke."; exit 1; }
rroot "$REMOTE_SCRIPT status" | head -30
pause

# ── 7. Persist ─────────────────────────────────────────────────────────────
stage "Keep the rules after a reboot"
say "Rules live in memory: a reboot removes them. A small systemd unit re-applies them after Docker starts."
if confirm "Install the systemd unit?"; then
  rroot "$REMOTE_SCRIPT save '$ADMIN_ADDRESSES'"
  rroot "printf '%s\n' '[Unit]' 'Description=fygs admin-only ports (issue 41)' 'After=docker.service network-online.target' 'Wants=network-online.target' '' '[Service]' 'Type=oneshot' 'RemainAfterExit=yes' 'ExecStart=$REMOTE_SCRIPT apply-from-conf' 'ExecStop=$REMOTE_SCRIPT rollback' '' '[Install]' 'WantedBy=multi-user.target' > /etc/systemd/system/fygs-firewall.service && systemctl daemon-reload && systemctl enable fygs-firewall.service"
  say "${GREEN}✓${RESET} enabled. To change the addresses later: $REMOTE_SCRIPT save '<addresses>' and apply."
else
  warn "Not persisted: after a reboot the four ports are public again."
fi
pause

# ── 8. SSH hardening ───────────────────────────────────────────────────────
stage "Optional: harden sshd"
say "Password logins off, root by key only, 3 tries, no X11. A drop-in file is tested with 'sshd -t' before it is loaded,"
say "and a fresh key-based connection must still work or the file is removed."
if confirm "Apply the sshd hardening?"; then
  rroot "mkdir -p /etc/ssh/sshd_config.d && printf '%s\n' 'PasswordAuthentication no' 'KbdInteractiveAuthentication no' 'PermitRootLogin prohibit-password' 'MaxAuthTries 3' 'X11Forwarding no' > /etc/ssh/sshd_config.d/99-fygs.conf && sshd -t"
  rroot "systemctl reload ssh 2>/dev/null || systemctl reload sshd"
  if rssh 'echo still-in'; then
    say "${GREEN}✓${RESET} a fresh key-based connection works"
  else
    warn "Cannot connect: use the provider console and delete /etc/ssh/sshd_config.d/99-fygs.conf, then reload sshd."; exit 1
  fi
  if confirm "Install fail2ban too (Debian/Ubuntu)?"; then
    rroot "DEBIAN_FRONTEND=noninteractive apt-get install -y fail2ban >/dev/null && systemctl enable --now fail2ban" && say "${GREEN}✓${RESET} fail2ban running"
  fi
else
  note "Skipped."
fi
pause

# ── 9. From outside ────────────────────────────────────────────────────────
stage "Check from ANOTHER network"
say "From this machine you are an admin address, so the ports look open. The real test is from outside:"
step "Switch to a phone hotspot (or any other network)."
step "In a bash shell, run:"
say "      for p in 22 80 443 8000 6001 6002; do (exec 3<>/dev/tcp/$VPS_IP_DEFAULT/\$p) 2>/dev/null && echo \"\$p OPEN\" || echo \"\$p closed\"; done"
step "Expected: 80 and 443 OPEN; 22, 8000, 6001 and 6002 closed."
say ""
say "Packet counters on the server (the DROP line grows when scanners hit the closed ports):"
rroot "$REMOTE_SCRIPT status" | grep -E "DROP|Chain" | head -6 | sed 's/^/  /' || true
confirm "From the other network: only 80 and 443 are open (22, 8000, 6001, 6002 closed)?" || warn "Then something is still exposed: re-run stage 5 or tell me the result."

# ── 10. Provider firewall ──────────────────────────────────────────────────
stage "Optional: a second wall at the provider"
say "A provider-level firewall drops traffic before it reaches the server at all."
open_url "https://www.ovh.com/manager/"
step "Look in OVH Manager for a network firewall that applies to this server's public IP ($VPS_IP_DEFAULT)."
note "I do not know whether your product offers one; availability depends on the product. If it does, mirror the same policy: allow 80/443 from anywhere,"
note "22, 8000, 6001 and 6002 only from your admin addresses. Do not rely on it alone: the rules installed above are the ones verified."
pause
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
